namespace UI_Desktop.Store;

internal static class StoreWindowsUpdateHeaderHtml
{
	internal static string Styles => ".nestg-update-control {\n    position: relative;\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    min-width: 0;\n    flex: 0 0 auto;\n    padding-left: 12px;\n    color: #f5f7fc;\n    font-family: \"Segoe UI Variable Text\", \"Segoe UI\", Arial, sans-serif;\n}\n.nestg-update-control::before {\n    content: \"\";\n    position: absolute;\n    top: 50%; left: 0;\n    width: 1px; height: 28px;\n    background: #354258;\n    transform: translateY(-50%);\n}\n.nestg-update-label { font-size: 14px; font-weight: 800; letter-spacing: .025em; white-space: nowrap; }\n.nestg-update-switch {\n    position: relative;\n    width: 48px; height: 44px;\n    padding: 0; border: 0;\n    flex: 0 0 auto;\n    background: transparent;\n    cursor: pointer;\n    touch-action: manipulation;\n}\n.nestg-update-switch::before {\n    content: \"\";\n    position: absolute;\n    inset: 10px 0;\n    border: 1px solid #414d62;\n    border-radius: 999px;\n    background: #30394e;\n    box-shadow: inset 0 1px 4px rgba(0, 0, 0, .3), 0 1px 4px rgba(0, 0, 0, .15);\n    transition: background-color .16s ease, border-color .16s ease;\n}\n.nestg-update-switch:hover:not(:disabled)::before { border-color: #8298b5; }\n.nestg-update-switch:focus-visible { outline: 2px solid #66c0f4; outline-offset: 2px; }\n.nestg-update-switch[aria-checked=\"true\"]::before {\n    background: #78522d;\n    border-color: #c2935e;\n    box-shadow: inset 0 1px 3px rgba(0, 0, 0, .28), 0 0 5px rgba(255, 179, 75, .16);\n}\n.nestg-update-switch:disabled { cursor: default; opacity: .7; }\n.nestg-update-icon {\n    display: grid;\n    position: absolute;\n    top: 15px;\n    width: 14px; height: 14px;\n    z-index: 1;\n    pointer-events: none;\n}\n.nestg-update-icon svg { width: 100%; height: 100%; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.nestg-update-icon-block { display: none; left: 5px; color: #ffe1b5; }\n.nestg-update-icon-allow { right: 5px; color: #bad4e7; }\n.nestg-update-switch[aria-checked=\"true\"] .nestg-update-icon-block { display: grid; }\n.nestg-update-switch[aria-checked=\"true\"] .nestg-update-icon-allow { display: none; }\n.nestg-update-thumb {\n    position: absolute;\n    top: 14px; left: 4px;\n    width: 16px; height: 16px;\n    border-radius: 50%;\n    background: #f1f5fa;\n    box-shadow: 0 1px 3px rgba(0, 0, 0, .3);\n    transition: transform .16s ease;\n}\n.nestg-update-switch[aria-checked=\"true\"] .nestg-update-thumb { transform: translateX(24px); }\n.nestg-update-control[aria-busy=\"true\"] .nestg-update-thumb::after {\n    content: \"\";\n    position: absolute;\n    inset: 3px;\n    border: 2px solid #78522d;\n    border-right-color: transparent;\n    border-radius: 50%;\n    animation: nestg-update-busy .7s linear infinite;\n}\n@keyframes nestg-update-busy { to { transform: rotate(360deg); } }\n.nestg-update-status {\n    position: absolute;\n    width: 1px; height: 1px;\n    padding: 0; overflow: hidden;\n    clip-path: inset(50%);\n    white-space: nowrap;\n}\n@media (max-width: 760px) {\n    .nestg-update-control { gap: 0; padding-left: 7px; }\n    .nestg-update-label { display: none; }\n}\n@media (max-width: 520px) {\n    .utility-left:has(.nestg-update-control) .nestg-warp-label,\n    .nestg-brand-warp:has(.nestg-update-control) .nestg-warp-label { display: none; }\n    .utility-left:has(.nestg-update-control) .nestg-warp-control,\n    .nestg-brand-warp:has(.nestg-update-control) .nestg-warp-control { gap: 0; padding-left: 4px; }\n    .utility-left:has(.nestg-update-control) .nestg-warp-install,\n    .nestg-brand-warp:has(.nestg-update-control) .nestg-warp-install { display: none; }\n    .nestg-update-control { padding-left: 4px; }\n    .nestg-update-switch { width: 44px; }\n    .nestg-update-icon-block { left: 4px; }\n    .nestg-update-icon-allow { right: 4px; }\n    .nestg-update-switch[aria-checked=\"true\"] .nestg-update-thumb { transform: translateX(20px); }\n}\n@media (prefers-reduced-motion: reduce) {\n    .nestg-update-switch::before, .nestg-update-thumb { transition: none; }\n    .nestg-update-control[aria-busy=\"true\"] .nestg-update-thumb::after { animation: none; }\n}";

	internal static string Script => "(() => {\n    const applyState = state => {\n        const control = document.querySelector('[data-update-control]');\n        if (!control || !state) return;\n        const toggle = control.querySelector('[data-update-switch]');\n        const status = control.querySelector('[data-update-status]');\n        if (!toggle || !status) return;\n        control.setAttribute('aria-busy', String(Boolean(state.busy)));\n        toggle.setAttribute('aria-label', 'Chặn cập nhật tự động của Windows');\n        toggle.setAttribute('aria-checked', String(Boolean(state.blocked)));\n        toggle.disabled = Boolean(state.busy) || !Boolean(state.canToggle);\n        toggle.title = 'Chặn Windows Update: ' + (state.busy ? 'Đang xử lý' : (state.detail || state.label || 'Chưa rõ'));\n        status.textContent = state.busy ? 'Đang xử lý' : (state.label || 'Chưa rõ');\n    };\n    const bind = () => {\n        const toggle = document.querySelector('[data-update-switch]');\n        if (!toggle) return;\n        toggle.addEventListener('click', () => {\n            if (toggle.disabled) return;\n            const blocked = toggle.getAttribute('aria-checked') !== 'true';\n            toggle.disabled = true;\n            const control = toggle.closest('[data-update-control]');\n            control?.setAttribute('aria-busy', 'true');\n            toggle.title = 'Chặn Windows Update: Đang xử lý';\n            control.querySelector('[data-update-status]').textContent = 'Đang xử lý';\n            window.chrome?.webview?.postMessage({ type: 'setWindowsUpdateBlocked', enabled: blocked });\n        });\n    };\n    window.__nestgWindowsUpdate = { setState: applyState };\n    if (document.readyState === 'loading')\n        document.addEventListener('DOMContentLoaded', bind, { once: true });\n    else bind();\n})();";

	internal static string Render()
	{
		return "<div class=\"nestg-update-control\" data-update-control aria-busy=\"true\">\n    <span class=\"nestg-update-label\" id=\"nestg-update-label\">Chặn Windows Update</span>\n    <button type=\"button\" class=\"nestg-update-switch\" role=\"switch\" data-update-switch\n        aria-label=\"Chặn cập nhật tự động của Windows\"\n        aria-describedby=\"nestg-update-status\" aria-checked=\"false\"\n        title=\"Đang kiểm tra Windows Update\" disabled>\n        <span class=\"nestg-update-icon nestg-update-icon-block\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 20 20\" fill=\"none\"><rect x=\"4.5\" y=\"9\" width=\"11\" height=\"8\" rx=\"1.8\"/><path d=\"M7 9V6.5a3 3 0 0 1 6 0V9\"/></svg>\n        </span>\n        <span class=\"nestg-update-icon nestg-update-icon-allow\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 20 20\" fill=\"none\"><path d=\"M15.5 8a6 6 0 1 0 .4 4\"/><path d=\"M15.5 3.5V8H11\"/></svg>\n        </span>\n        <span class=\"nestg-update-thumb\" aria-hidden=\"true\"></span>\n    </button>\n    <span class=\"nestg-update-status\" id=\"nestg-update-status\" data-update-status\n        role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">Đang kiểm tra</span>\n</div>";
	}
}
